import os
base = os.path.dirname(os.path.abspath(__file__))
out = os.path.join(base, "stdlib")

def F(n,r,p,c,b):
    L=[f"// {c}"]
    if r=="void": L.append(f"ط¯ط§ظ„ط© {n}({p}) {{")
    else: L.append(f"ط¯ط§ظ„ط© {n}({p}) -> {r} {{")
    for l in b: L.append(f"    {l}")
    last=b[-1].strip() if b else ""
    has_return=last.startswith("ط§ط±ط¬ط¹") and last.endswith(";")
    if not has_return:
        if r=="طµط­ظٹط­": L.append("    ط§ط±ط¬ط¹ طµط­ظٹط­ط§ظ‹;")
        elif r=="ظ†طµ": L.append('    ط§ط±ط¬ط¹ "";')
        elif r=="ط¹ط´ط±ظٹ": L.append("    ط§ط±ط¬ط¹ 0.0;")
        elif r.endswith("[]"):
            L.append(f"    {r} ظ†ط§طھط¬ = [];"); L.append("    ط§ط±ط¬ط¹ ظ†ط§طھط¬;")
    L.append("}")
    return "\n".join(L)

def write_lib(cat,name,desc,funcs):
    d=os.path.join(out,cat); os.makedirs(d,exist_ok=True)
    h=f"// ط¶ ظ…ظƒطھط¨ط©: {name}\n// ط§ظ„ظپط¦ط©: {cat}\n// ط§ظ„ظˆطµظپ: {desc}\n\n"
    with open(os.path.join(d,f"{name}.ض"),"w",encoding="utf-8") as f:
        f.write(h+"\n\n".join(F(*fn) for fn in funcs)+"\n")

total=0
def W(cat,name,desc,funcs):
    global total; write_lib(cat,name,desc,funcs); total+=1; print(f"  [{total:3d}/100] {cat}/{name}")

